import { applyMiddleware, createStore } from "redux";
import { reducers } from "./reducers/rootReducer";
import { thunk } from "redux-thunk";
import { addProduct, deleteProduct } from "./actions/productActions";
import axios from "axios";

export const getProductsMiddleWare = () => {
  return (dispatch) => {
    axios("https://api.escuelajs.co/api/v1/products").then((res) =>
      dispatch(addProduct(res.data))
    );
  };
};

export const deleteProductMiddleWare = (id) => {
  return (dispatch) => {
    awaxios.delete(`https://api.escuelajs.co/api/v1/products/${id}`),
      dispatch(deleteProduct(id));
  };
};

const store = createStore(reducers, applyMiddleware(thunk));

export default store;
